/**
 * build-figures-index — produces docs/figures-index.md from the
 * filesystem.  Scans every `content/<paper>/<chapter>/rendered/*.svg`
 * (excluding auto-generated dvisvgm output) and emits a master
 * catalogue table for editorial review.
 *
 * Authoring rule (per local/illustration-author skill):
 *   <slug>.svg              — primary light-mode SVG  [REQUIRED]
 *   <slug>.dark.svg         — optional hand-tuned dark override
 *   <slug>.prompt.md        — prompt sidecar (margin note in PDF)
 *
 * A "figure family" = one slug; variants A/B/… within the same
 * recommended slot are detected by a -A/-B/… suffix on the slug.
 * The table groups by chapter, one row per variant.  Columns:
 *
 *   | Stub | Light | Dark | Prompt | Variants | Wired in |
 *
 * "Light" / "Dark" cells render scaled thumbnails (160px wide)
 * linking to the full file.  When no hand-tuned dark SVG is
 * present the light SVG is reused with a note that the viewer
 * applies an invert+hue-rotate filter at render time.
 *
 * "Wired in" links to the .md block that currently embeds the
 * figure (scanned by grep'ing the chapter dir for the slug).
 *
 * Run:  bun run pipeline/build-figures-index.ts
 *
 * @module content/pipeline/build-figures-index
 */

import { readFileSync, writeFileSync, readdirSync, existsSync, statSync } from "fs";
import { join, basename, relative, dirname } from "path";

const REPO_ROOT = join(import.meta.dir, "..", "..");
const CONTENT_ROOT = join(REPO_ROOT, "content", "quantum-observable-universe");
const OUT = join(REPO_ROOT, "docs", "figures-index.md");
const THUMB_W = 540;

interface SvgEntry {
  slug: string;
  family: string;
  variant?: string;
  chapter: string;
  svgPath: string;       // repo-relative
  darkPath?: string;     // repo-relative
  promptPath?: string;
  title?: string;        // first `# …` heading of the prompt sidecar
  promptBody?: string;   // remainder of the prompt sidecar
  wiredIn?: string;      // chapter-relative .md filename if found
}

/**
 * Pull `# Title` heading + body out of a `.prompt.md` file.
 * Mirrors the parsing logic in
 * `content/pipeline/render-latex.ts:readPromptSidecar`.
 */
function parsePromptSidecar(path: string): { title?: string; body: string } {
  const raw = readFileSync(path, "utf-8").replace(/\r/g, "");
  const lines = raw.split("\n");
  let title: string | undefined;
  let bodyStart = 0;
  for (let i = 0; i < lines.length; i++) {
    const ln = lines[i].trim();
    if (ln === "") continue;
    const h = ln.match(/^#\s+(.*\S)\s*$/);
    if (h) {
      title = h[1].trim();
      bodyStart = i + 1;
    }
    break;
  }
  const body = lines.slice(bodyStart).join("\n").replace(/\s+/g, " ").trim();
  return { title, body };
}

function isDvisvgmOutput(path: string): boolean {
  try {
    const head = readFileSync(path, "utf-8").slice(0, 200);
    return head.includes("generated by dvisvgm");
  } catch {
    return false;
  }
}

function listSvgsInChapter(chapterDir: string): string[] {
  const renderedDir = join(chapterDir, "rendered");
  if (!existsSync(renderedDir)) return [];
  return readdirSync(renderedDir)
    .filter((f) => f.endsWith(".svg") && !f.endsWith(".dark.svg"))
    .map((f) => join(renderedDir, f));
}

function parseSlug(filename: string): { slug: string; family: string; variant?: string } {
  const slug = basename(filename, ".svg");
  const m = slug.match(/^(.+)-([A-Z])$/);
  return m
    ? { slug, family: m[1], variant: m[2] }
    : { slug, family: slug };
}

function findChapters(): string[] {
  return readdirSync(CONTENT_ROOT)
    .filter((d) => {
      const p = join(CONTENT_ROOT, d);
      try {
        return statSync(p).isDirectory() && existsSync(join(p, "rendered"));
      } catch {
        return false;
      }
    })
    .sort();
}

function findWiredIn(chapterDir: string, slug: string): string | undefined {
  // grep the chapter's .md files for `(rendered/<slug>.svg)`
  const files = readdirSync(chapterDir).filter((f) => f.endsWith(".md"));
  const needle = `rendered/${slug}.svg`;
  for (const f of files) {
    try {
      const txt = readFileSync(join(chapterDir, f), "utf-8");
      if (txt.includes(needle)) return f;
    } catch {
      /* ignore */
    }
  }
  return undefined;
}

function loadEntry(svgPath: string, chapter: string, chapterDir: string): SvgEntry | null {
  if (isDvisvgmOutput(svgPath)) return null;
  const { slug, family, variant } = parseSlug(svgPath);
  const dirPath = dirname(svgPath);
  const darkPath = join(dirPath, `${slug}.dark.svg`);
  const promptPath = join(dirPath, `${slug}.prompt.md`);
  let title: string | undefined;
  let promptBody: string | undefined;
  if (existsSync(promptPath)) {
    const parsed = parsePromptSidecar(promptPath);
    title = parsed.title;
    promptBody = parsed.body;
  }
  return {
    slug,
    family,
    variant,
    chapter,
    svgPath: relative(REPO_ROOT, svgPath),
    darkPath: existsSync(darkPath) ? relative(REPO_ROOT, darkPath) : undefined,
    promptPath: existsSync(promptPath) ? relative(REPO_ROOT, promptPath) : undefined,
    title,
    promptBody,
    wiredIn: findWiredIn(chapterDir, slug),
  };
}

function relFromIndex(repoRelativePath: string): string {
  return `../${repoRelativePath}`;
}

function chapterTitle(chapter: string): string {
  return chapter
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function summary(promptText: string, maxLen = 280): string {
  const oneLine = promptText.replace(/\s+/g, " ").trim();
  return oneLine.length > maxLen
    ? oneLine.slice(0, maxLen - 1).trimEnd() + "…"
    : oneLine;
}

function escapeCellMd(s: string): string {
  // table-cell-safe: no pipes, no newlines
  return s.replace(/\|/g, "\\|").replace(/\n+/g, " ");
}

function thumb(svgRepoPath: string, alt: string): string {
  const url = relFromIndex(svgRepoPath);
  return `<a href="${url}" title="${escapeCellMd(alt)}"><img src="${url}" width="${THUMB_W}" alt="${escapeCellMd(alt)}"></a>`;
}

function variantsCell(family: string, all: SvgEntry[], current: SvgEntry): string {
  const sibs = all
    .filter((e) => e.family === family && e.slug !== current.slug)
    .sort((a, b) => (a.variant ?? "").localeCompare(b.variant ?? ""));
  if (sibs.length === 0) return "—";
  return sibs
    .map((e) => `[${e.variant ?? "•"}](${relFromIndex(e.svgPath)})`)
    .join(" · ");
}

function wiredCell(e: SvgEntry): string {
  if (!e.wiredIn) return "*(not wired)*";
  const path = `content/quantum-observable-universe/${e.chapter}/${e.wiredIn}`;
  return `[\`${e.chapter}/${e.wiredIn}\`](${relFromIndex(path)})`;
}

function main() {
  const chapters = findChapters();
  const lines: string[] = [];
  let totalAuthored = 0;
  let totalDarkOverrides = 0;
  let totalWired = 0;

  lines.push("# Figures index — *On the Mechanics of Quantum Observable Universes*");
  lines.push("");
  lines.push("Auto-generated by [`content/pipeline/build-figures-index.ts`](../content/pipeline/build-figures-index.ts).");
  lines.push("Do not edit by hand — re-run the script after adding or modifying a figure under");
  lines.push("`content/quantum-observable-universe/<chapter>/rendered/`.");
  lines.push("");
  lines.push("**Authoring source-of-truth:**");
  lines.push("");
  lines.push("- Specification + placement: [`docs/illustration-recommendations.md`](illustration-recommendations.md)");
  lines.push("- Skill (prompt → SVG): [`.claude/skills/local/illustration-author.md`](../.claude/skills/local/illustration-author.md)");
  lines.push("- Coordination ledger: [`docs/coordination/illustrations.md`](coordination/illustrations.md)");
  lines.push("");
  lines.push("**Reading each entry:**");
  lines.push("");
  lines.push("- **Stub** — repository-wide unique slug (filename without `.svg`).");
  lines.push("- **Title** — short generated name from the first `# …` heading of the prompt sidecar; also rendered under the figure in the printed PDF via `\\figtitle{…}`.");
  lines.push("- **Light + Dark previews** — large side-by-side thumbnails (click for full size). When a hand-tuned `<stem>.dark.svg` sibling exists, the right side shows it; otherwise the right side reuses the light SVG (the viewer applies CSS `invert(1) hue-rotate(180deg)` to the light SVG at render time).");
  lines.push("- **Prompt** — the textual prompt that produced the SVG (also surfaced in the printed PDF margin via `\\figprompt{…}`).");
  lines.push("- **Variants** — sibling design alternatives in the same recommended slot.");
  lines.push("- **Wired in** — the chapter `.md` block that currently embeds this SVG; `(not wired)` means the figure is on disk but not yet referenced from any block.");
  lines.push("");

  // Collect all entries first so we can compute totals + variant siblings.
  const allEntries: SvgEntry[] = [];
  for (const chapter of chapters) {
    const chapterDir = join(CONTENT_ROOT, chapter);
    const svgs = listSvgsInChapter(chapterDir);
    for (const p of svgs) {
      const e = loadEntry(p, chapter, chapterDir);
      if (e) allEntries.push(e);
    }
  }
  totalAuthored = allEntries.length;
  totalDarkOverrides = allEntries.filter((e) => e.darkPath).length;
  totalWired = allEntries.filter((e) => e.wiredIn).length;

  lines.push(`**Status:** ${totalAuthored} authored figure(s) across ${new Set(allEntries.map((e) => e.chapter)).size} chapter(s) · ${totalWired} wired into a block · ${totalDarkOverrides} hand-tuned dark-mode override(s).`);
  lines.push("");

  for (const chapter of chapters) {
    const entries = allEntries
      .filter((e) => e.chapter === chapter)
      .sort((a, b) => a.slug.localeCompare(b.slug));
    if (entries.length === 0) continue;

    lines.push(`## ${chapterTitle(chapter)}`);
    lines.push("");

    for (const e of entries) {
      const titleStr = e.title ?? "*(no title)*";
      const lightUrl = relFromIndex(e.svgPath);
      const darkUrl = e.darkPath ? relFromIndex(e.darkPath) : lightUrl;
      const isFilterDark = !e.darkPath;
      const varCell = variantsCell(e.family, allEntries, e);
      const wiredStr = wiredCell(e);

      // Per-figure stacked panel: header + two big side-by-side previews
      // (light + dark) + prompt + metadata.  HTML <img> width is honoured
      // by GitHub's renderer.
      lines.push(`### \`${e.slug}\` — ${escapeCellMd(titleStr)}`);
      lines.push("");
      lines.push(`<a href="${lightUrl}"><img src="${lightUrl}" width="${THUMB_W}" alt="${escapeCellMd(titleStr)}"></a>  <a href="${darkUrl}"><img src="${darkUrl}" width="${THUMB_W}" alt="${escapeCellMd(titleStr)} (dark${isFilterDark ? ' — filter inverted' : ''})"></a>`);
      lines.push("");
      lines.push(`<sub>**Light** *(primary)*  ·  **Dark** *${isFilterDark ? '(viewer applies invert + hue-rotate filter at render time)' : '(hand-tuned override)'}*</sub>`);
      lines.push("");
      if (e.promptBody) {
        lines.push(`> ${summary(e.promptBody)}`);
        lines.push("");
      }
      lines.push(`**Variants:** ${varCell} · **Wired in:** ${wiredStr}${e.promptPath ? ` · **Prompt file:** [\`${basename(e.promptPath)}\`](${relFromIndex(e.promptPath)})` : ""}`);
      lines.push("");
      lines.push("---");
      lines.push("");
    }
  }

  lines.push("");
  lines.push(`<sub>Generated ${new Date().toISOString().slice(0, 10)} from ${totalAuthored} authored SVG file(s).</sub>`);
  lines.push("");

  writeFileSync(OUT, lines.join("\n"));
  console.log(`✓ Wrote ${relative(REPO_ROOT, OUT)} — ${totalAuthored} figures across ${new Set(allEntries.map((e) => e.chapter)).size} chapters (${totalWired} wired, ${totalDarkOverrides} dark overrides).`);
}

main();
